<script setup>
import {computed, ref, watch, onBeforeUnmount} from 'vue'
import {useAxiosAuth} from '@/composables/axios-auth'
import {plansOnDate, calendarDays, shiftCalendarDate} from '@/features/planner/lib/calendar'
import {BUCKET_BY_TYPE} from '@/features/planner/lib/plannerBuckets'
import {bucketTitle, estimateMinutes, progressFromApi} from '@/features/planner/dailyPlanner'
import {buildWorkoutCompletionSummary} from '@/features/planner/lib/workoutProgress'
const props = defineProps({plans:Array, date:String, loading:Boolean, offline:Boolean, compact:Boolean})
const emit = defineEmits(['create','edit','players','duplicate','date','management','check-in'])
const {axiosGet} = useAxiosAuth()
const filter = ref('All'), progress = ref([]), progressLoading = ref(false), progressError = ref('')
const dayPlans = computed(() => plansOnDate(props.plans || [],props.date))
const scheduled = computed(() => new Set(dayPlans.value.flatMap(p=>p.assignedPlayerIds || [])).size)
const blocks = computed(() => dayPlans.value.flatMap(plan=>(plan.buckets || []).filter(b=>BUCKET_BY_TYPE[b.type]?.kind==='content').map((bucket,index)=>({plan,bucket,index}))).sort((a,b)=>(a.bucket.startTime || '99:99').localeCompare(b.bucket.startTime || '99:99')))
const shown = computed(() => blocks.value.filter(({plan})=>filter.value==='All'||(filter.value==='Individuals'?plan.assignedPlayerIds.length===1:plan.assignedPlayerIds.length>1)))
const upcoming = computed(() => (props.plans || []).filter(p=>p.date>props.date).sort((a,b)=>a.date.localeCompare(b.date)).slice(0,3))
const previousPlans = computed(() => plansOnDate(props.plans || [],shiftCalendarDate(props.date,-1)))
const notes = computed(() => dayPlans.value.flatMap(plan=>(plan.buckets || []).filter(b=>b.type==='coach_notes'&&b.note).map(b=>({plan,note:b.note}))))
const weeks = computed(() => calendarDays(props.date).map(date=>({date,minutes:plansOnDate(props.plans || [],date).reduce((sum,p)=>sum+estimateMinutes(p),0)})))
const maxMinutes = computed(() => Math.max(1,...weeks.value.map(d=>d.minutes)))
const completion = computed(() => !progress.value.length || progressError.value ? null : Math.round(progress.value.reduce((sum,r)=>sum+buildWorkoutCompletionSummary(r.plan,r.progress).completionPct,0)/progress.value.length))
const checkIns = computed(() => progress.value.map(row => {
  const summary = buildWorkoutCompletionSummary(row.plan, row.progress)
  const labels = {not_started: 'Not started', in_progress: summary.completedItems ? 'In progress' : 'Started', completed: 'Submitted', reviewed: 'Reviewed'}
  return {...row, summary, statusLabel: labels[summary.status], name: [row.player?.first_name, row.player?.last_name].filter(Boolean).join(' ') || row.player?.name?.full || 'Player'}
}))
let generation = 0
const loadProgress = async () => {
  const request = ++generation; progress.value=[]; progressError.value=''; progressLoading.value=true
  const published = dayPlans.value.filter(p=>p.status==='published')
  const responses = await Promise.allSettled(published.map(async plan=>{
    const {data} = await axiosGet(`coach/daily-plans/${plan.id}/progress`)
    if (!Array.isArray(data?.data?.players)) throw new Error('Unavailable')
    return data.data.players.map(row=>({plan,player:row.player,progress:progressFromApi(row.progress,plan.id)}))
  }))
  if(request!==generation)return
  progress.value=responses.filter(r=>r.status==='fulfilled').flatMap(r=>r.value)
  if(responses.some(r=>r.status==='rejected'))progressError.value='Some player progress could not be loaded. Open Player progress to retry.'
  progressLoading.value=false
}
watch(() => JSON.stringify([props.date,dayPlans.value.map(p=>[p.id,p.status,p.publishedAt,p.buckets,p.assignedPlayerIds])]), loadProgress, {immediate:true})
onBeforeUnmount(()=>{generation++})
const clock = time => time || 'Time not set'
function editFirst() { dayPlans.value.length ? emit('edit',dayPlans.value[0]) : emit('create',props.date) }
function blockCompleted(row) {
  if(row.plan.status!=='published'||progressLoading.value||progressError.value)return '—'
  const items = row.bucket.items || []
  if(!items.length)return '—'
  return progress.value.filter(r=>r.plan.id===row.plan.id && items.every(it=>r.progress?.items?.[it.id]?.done)).length
}
</script>
<template>
  <div class="day-dashboard" :class="{compact}">
    <div v-if="!compact" class="day-stats"><article><span>♟</span><div><strong>{{ scheduled }}</strong><p>Players scheduled</p><small>{{ dayPlans.length }} workout plans</small></div></article><article><span class="green">◔</span><div><strong>{{ progressLoading?'…':completion==null?'—':completion+'%' }}</strong><p>Plan completion</p><small>Published workouts · selected day</small></div></article><article><span class="red">◈</span><div><strong>{{ blocks.length }}</strong><p>Training blocks</p><small>{{ dayPlans.filter(p=>p.status==='draft').length }} draft plans</small></div></article><article><span class="blue">▥</span><div><strong>{{ blocks.filter(r=>BUCKET_BY_TYPE[r.bucket.type]?.strength).length }}</strong><p>Strength blocks</p><small>Scheduled in workouts</small></div></article></div>
    <p v-if="offline" role="alert" class="day-message">Plans could not be refreshed. Displayed information may be out of date.</p><p v-if="progressError" role="alert" class="day-message">{{ progressError }}</p>
    <div class="day-main"><section class="day-panel schedule"><header><h2>Day’s Schedule</h2><button @click="emit('management')">Team tools →</button></header><div class="day-filters"><button v-for="f in ['All','Groups','Individuals']" :key="f" :class="{active:filter===f}" @click="filter=f">{{ f }}</button></div><p v-if="loading" class="empty" role="status">Loading plans…</p><p v-else-if="!shown.length" class="empty">{{ dayPlans.length?'No training blocks match this view. Edit a plan to add exercises.':'No workouts scheduled. Create a plan for this day.' }}</p><div v-for="row in shown" :key="row.plan.id+row.bucket.type" class="timeline-row" :style="{'--block-color':BUCKET_BY_TYPE[row.bucket.type]?.color}"><div class="block-time">{{ clock(row.bucket.startTime) }}<small v-if="row.bucket.endTime">{{ row.bucket.endTime }}</small></div><div class="timeline-dot"></div><div class="block-content"><div><h3>{{ bucketTitle(row.bucket.type) }}</h3><span class="block-tag">{{ row.plan.status==='published'?'Published':'Draft' }}</span></div><p>{{ row.bucket.location || 'Location not set' }}</p><small>{{ row.plan.name }} · {{ row.bucket.items?.map(i=>i.name||i.title).filter(Boolean).slice(0,3).join(' / ') || 'No exercises added' }}</small></div><div class="block-count" :title="row.plan.status==='published'?'Players who completed every exercise in this block':'Draft workouts are not available to players'">{{ blockCompleted(row) }}/{{ row.plan.assignedPlayerIds.length }}<small>complete</small></div><button @click="emit('edit',row.plan)">View</button></div>
      <div v-if="dayPlans.length" class="plan-actions"><div v-for="plan in dayPlans" :key="plan.id"><span>{{ plan.name }}</span><button @click="emit('edit',plan)">{{ plan.status==='published'?'Edit workout':'Review & publish' }}</button><button v-if="plan.status==='published'" @click="emit('players',plan)">Player progress</button><button v-if="!compact" @click="emit('duplicate',plan)">Duplicate</button></div></div><footer><button class="primary" @click="emit('create',date)">＋ Add workout</button><details v-if="previousPlans.length" class="copy-menu"><summary>Copy from previous day</summary><button v-for="plan in previousPlans" :key="plan.id" @click="emit('duplicate',plan)">{{ plan.name }}</button></details></footer></section>
    <aside><section v-if="!compact" class="day-panel"><header><h2>Daily Focus</h2><button class="link" @click="editFirst">Edit</button></header><div class="focus"><span>◎</span><div><h3>{{ dayPlans[0]?.primaryGoal || 'Set your daily focus' }}</h3><p>{{ dayPlans[0]?.name || 'Create a workout to plan the day.' }}</p></div></div></section><section class="day-panel"><header><h2>Workout check-ins</h2><button class="link" :disabled="progressLoading" @click="loadProgress">Refresh</button></header>
      <p>Player progress for workouts scheduled today. Select a player to review their results.</p>
      <p v-if="progressLoading" role="status">Loading check-ins…</p>
      <p v-else-if="!checkIns.length">{{ progressError ? 'Check-ins unavailable. Refresh to retry.' : 'No players assigned to published workouts for this day.' }}</p>
      <button v-for="row in checkIns" :key="row.plan.id + ':' + row.player.id" class="check-in-card" @click="emit('check-in', row.plan, row.player.id)">
        <span class="check-in-heading"><strong>{{ row.name }}</strong><strong>{{ row.summary.completionPct }}%</strong></span>
        <span class="check-in-plan">{{ row.plan.name }}</span>
        <span class="check-in-heading"><span class="check-in-status" :class="row.summary.status">{{ row.statusLabel }}</span><span>{{ row.summary.completedItems }}/{{ row.summary.totalItems }} tasks</span></span>
        <progress :value="row.summary.completionPct" max="100" :aria-label="`${row.name}: ${row.summary.completionPct}% complete`"></progress>
        <small v-if="row.progress?.completedAt && row.summary.completionPct < 100">Submitted with unfinished tasks</small>
        <small>View workout results →</small>
      </button>
    </section><section v-if="!compact" class="day-panel"><header><h2>Notes</h2><button class="link" @click="editFirst">＋ Edit notes</button></header><article v-for="(note,i) in notes" :key="i" class="coach-note"><strong>{{ note.plan.name }}</strong><p>{{ note.note }}</p></article><p v-if="!notes.length">No coach notes yet. Add a Coach Notes block in the workout editor.</p></section></aside></div>
    <div v-if="!compact" class="day-bottom"><section class="day-panel"><h2>Attendance</h2><div class="attendance-number">{{ scheduled }}</div><p>Players assigned to workouts</p><small>Attendance is not recorded here. Assignment and workout completion do not confirm attendance.</small></section><section class="day-panel"><h2>Planned Training Volume</h2><div class="volume-chart"><button v-for="day in weeks" :key="day.date" :aria-label="`${day.date}: ${day.minutes} estimated minutes`" @click="emit('date',day.date)"><strong>{{ day.minutes }}</strong><div><i :style="{height:Math.max(2,day.minutes/maxMinutes*80)+'px'}" :class="{selected:day.date===date}"></i></div><small>{{ new Date(day.date+'T12:00:00').toLocaleDateString(undefined,{weekday:'short'}) }}</small></button></div><small>Estimated workout minutes · not measured player workload</small></section><section class="day-panel"><header><h2>Upcoming</h2><button class="link" @click="emit('date',upcoming[0]?.date || shiftCalendarDate(date,1))">Next →</button></header><button v-for="plan in upcoming" :key="plan.id" class="upcoming-plan" @click="emit('date',plan.date)"><b>{{ plan.date.slice(5) }}</b><span>{{ plan.name }}<small>{{ plan.status==='published'?'Published':'Draft' }}</small></span></button><p v-if="!upcoming.length">No upcoming workouts scheduled.</p></section></div>
  </div>
</template>
<style scoped>
.day-dashboard{color:#edf2fa}.day-stats{display:grid;grid-template-columns:repeat(4,1fr);gap:14px;margin-bottom:20px}.day-stats article,.day-panel{background:linear-gradient(120deg,#111f30,#091421);border:1px solid #2c3c51;border-radius:9px;padding:20px;min-width:0}.day-stats article{display:flex;gap:17px;align-items:flex-start}.day-stats article>span{font-size:30px;color:#92b0d8}.day-stats strong{font-size:27px;font-weight:750}.day-stats p{margin:4px 0 10px}.day-dashboard p{font-size:12px;line-height:1.6;color:#a6b6cb}.day-dashboard small{font-size:10px;line-height:1.6;color:#8fa3be}.day-main{display:grid;grid-template-columns:minmax(0,2.2fr) minmax(260px,1fr);gap:18px;align-items:flex-start}.day-main aside{display:grid;gap:16px}.day-panel header{display:flex;align-items:center;justify-content:space-between;gap:10px;margin-bottom:20px}.day-panel h2{font-size:14px;text-transform:uppercase;font-weight:750;letter-spacing:.5px}.day-panel h3{font-size:13px;font-weight:700}.day-dashboard button{background:#162436;border:1px solid #33465e;border-radius:5px;padding:8px 12px;color:#d6e1ef;font-size:11px}.day-dashboard button:hover{border-color:#8099bc}.day-dashboard button:focus-visible,.copy-menu summary:focus-visible{outline:2px solid #76b8ff;outline-offset:3px}.day-filters{display:flex;gap:10px;margin-bottom:18px}.day-filters .active,.day-dashboard .primary{background:linear-gradient(100deg,#e4212d,#940d16);border-color:#ff323b;color:white}.timeline-row{display:flex;align-items:center;gap:15px;padding:18px 0;border-top:1px solid #2a3c51;position:relative}.block-time{font-size:11px;flex:0 0 69px;color:#afc0d6}.block-time small{display:block}.timeline-dot{position:relative;flex:0 0 12px;height:12px;border-radius:50%;background:var(--block-color)}.timeline-dot:after{content:'';position:absolute;left:5px;top:15px;width:1px;height:74px;background:var(--block-color);opacity:.4}.block-content{flex:1;min-width:0}.block-content>div{display:flex;align-items:center;gap:10px;flex-wrap:wrap}.block-content p{margin:5px 0}.block-tag{border:1px solid var(--block-color);color:var(--block-color);border-radius:3px;padding:2px 5px;font-size:9px;text-transform:uppercase}.block-count{font-size:12px;color:#61d69a;white-space:nowrap}.block-count small{display:block}.plan-actions{border-top:1px solid #2a3c51;padding-top:12px}.plan-actions>div{display:flex;gap:8px;flex-wrap:wrap;margin-bottom:10px;align-items:center}.plan-actions span{flex:1;font-size:12px;min-width:120px}.schedule footer{display:flex;align-items:flex-start;justify-content:space-between;gap:12px;margin-top:22px}.copy-menu{font-size:11px;color:#a9bdd7}.copy-menu summary{cursor:pointer;padding:10px;border:1px solid #33465e;border-radius:5px}.copy-menu button{display:block;margin-top:8px}.focus{display:flex;gap:18px}.focus>span{font-size:40px;color:#f5353d}.readiness-row{display:grid;grid-template-columns:1fr auto;gap:5px;margin-top:17px;font-size:12px}.readiness-row small{grid-column:1/-1}.readiness-row strong{color:#72d8a0}.day-dashboard .link{border:0;background:none;color:#71b2f2;padding:0}.full{width:100%;margin-top:18px}.coach-note{padding:12px;border:1px solid #2b4059;border-radius:6px;margin-bottom:8px}.coach-note strong{font-size:12px}.coach-note p{white-space:pre-wrap;margin-top:8px}.day-bottom{display:grid;grid-template-columns:1fr 1.1fr 1.1fr;gap:16px;margin-top:18px}.attendance-number{font-size:48px;font-weight:750;color:#7dc8b2;margin:22px 0 6px}.volume-chart{display:flex;gap:7px;margin:20px 0 10px}.volume-chart button{flex:1;padding:0;border:0;background:none;min-width:0}.volume-chart button>div{height:85px;display:flex;align-items:flex-end}.volume-chart i{display:block;width:100%;background:linear-gradient(#36cb90,#168464);border-radius:3px 3px 0 0}.volume-chart i.selected{background:linear-gradient(#f63b42,#b31626)}.volume-chart strong{font-size:10px;color:#a7bed8}.upcoming-plan{width:100%;display:flex;gap:13px;text-align:left;margin-bottom:8px}.upcoming-plan b{color:#ff4951}.upcoming-plan span{flex:1}.upcoming-plan small{display:block}.empty{padding:35px 10px}.day-message{margin-bottom:15px;color:#f6c38b!important}@media(max-width:1100px){.day-stats{grid-template-columns:repeat(2,1fr)}.day-main{grid-template-columns:1fr}.day-main aside{grid-template-columns:repeat(3,minmax(0,1fr))}}@media(max-width:700px){.day-main aside,.day-bottom{grid-template-columns:1fr}.day-stats article,.day-panel{padding:14px}.day-stats article{gap:8px}.day-stats article>span{display:none}.timeline-row{flex-wrap:wrap;gap:9px}.block-time{flex-basis:62px}.block-content{flex-basis:calc(100% - 110px)}.block-count{margin-left:85px}.schedule footer{flex-wrap:wrap}}
</style>

<style scoped>
.check-in-card{display:block;width:100%;text-align:left!important;padding:14px!important;margin:10px 0;background:#111e31!important;border:1px solid #2e425d!important;border-radius:10px!important;color:#dfebfa!important}.check-in-heading{display:flex;justify-content:space-between;align-items:center;gap:8px;font-size:12px}.check-in-heading strong{font-size:14px}.check-in-plan{display:block;font-size:12px;color:#9ebbd6;margin:7px 0}.check-in-status{padding:3px 7px;border-radius:5px;background:#253249;color:#b7c7db}.check-in-status.in_progress{background:#493819;color:#ffd18a}.check-in-status.completed,.check-in-status.reviewed{background:#123f35;color:#78e7b0}.check-in-card progress{width:100%;height:5px;accent-color:#39d5a5;margin:12px 0 4px}.check-in-card small{display:block;color:#9ebbd6;font-size:11px;margin-top:5px}.check-in-card:focus-visible{outline:2px solid #7db9fb;outline-offset:2px}
</style>

<style scoped>
.compact .day-main{grid-template-columns:minmax(0,1.4fr) minmax(220px,1fr)}.compact .timeline-row{flex-wrap:wrap}.compact .day-panel{min-width:0}@media(max-width:1250px){.compact .day-main{grid-template-columns:minmax(0,1fr)}}
</style>
